const state={players:[],filtered:[],query:'',rank:'all',origin:'all',event:'all',sort:'power',dir:-1,tab:'overview',swordlandPage:'participants',plannerUnlocked:false,planner:{assignments:{},buildingAssignments:{},availabilityResponses:{},looterAssignments:{}}};
const swordlandStorageKey='bro671-swordland-public-ids';
