let plannerCryptoKey=null;
let plannerNext=null;
const $=s=>document.querySelector(s);
const fmt=n=>new Intl.NumberFormat('en',{notation:Number(n)>=1e6?'compact':'standard',maximumFractionDigits:1}).format(n||0);
const exact=n=>n==null?'—':new Intl.NumberFormat('en').format(n);
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const asset=p=>!p?'':p.startsWith('/')?'https://mightpulse.com'+p:p;
const tcLabel=n=>{if(!n)return'—';if(n<=30)return`TC ${n}`;const tier=Math.floor(n/5)-6,stage=n%5;return tier>0?`TG${tier}${stage?'-'+stage:''}`:`TC ${n}`};
const board=(x,name)=>(x.r?.leaderboards||[]).find(b=>b.name===name)||{};
const rLevel=x=>({Leader:5,R4:4,R3:3,R2:2,R1:1}[x.p.alliance.rank_label]||0);
const sortValue=(x,key)=>({name:x.p.nick_name,id:x.id,power:x.p.power,rlevel:rLevel(x),kills:x.p.kills,mystic:x.r?.mystic_trial,mysticRank:-(x.r?.mystic_rank||99999),migrant:x.r?.migrant_score,coliseum:board(x,'Coliseum').value,forest:board(x,'Forest of Life').value,crystal:board(x,'Crystal Cave').value,knowledge:board(x,'Knowledge Nexus').value,molten:board(x,'Molten Fort').value,radiant:board(x,'Radiant Spire').value}[key]??-1);

fetch(`data.json?ts=${Date.now()}`,{cache:'no-store'}).then(r=>r.json()).then(data=>{
  const inkIds=new Set(data.origin_tags?.INK||[]);
  state.players=data.players.map(row=>({id:row.public_id,origin:row.origin==='INK'||inkIds.has(row.public_id)?'INK':'BRO',membership:row.membership||((data.origin_tags?.EX_BRO||[]).includes(row.public_id)?'former':row.origin==='INK'?'guest':'current'),swordland:Boolean(row.swordland||row.swordland_role),swordlandRole:row.swordland_role||'',raw:row.profile,p:row.profile.player,r:row.profile.ranks,heroes:row.profile.heroes||[],gear:row.profile.gov_gear||{}}));
  loadSwordlandSelections();
  const rankedPlayers=state.players.filter(x=>x.membership!=='former');
  ['power','kills','mystic','migrant'].forEach(key=>assignRanks(rankedPlayers,key,'aRanks'));
  const currentBro=state.players.filter(x=>x.membership==='current');
  const trialRankKeys=['mystic','coliseum','forest','crystal','knowledge','molten','radiant'];
  trialRankKeys.forEach(key=>{assignRanks(currentBro,key,'broRanks');assignRanks(rankedPlayers,key,'poolRanks')});
  $('#retrievedAt').textContent=new Date(data.retrieved_at).toLocaleString();
  renderMetrics(data);apply();
}).catch(()=>{$('#playerList').innerHTML='<div class="empty">Unable to load player data.</div>'});

function assignRanks(pool,key,prop){const sorted=[...pool].sort((a,b)=>sortValue(b,key)-sortValue(a,key));let last=null,rank=0;sorted.forEach((x,i)=>{const v=sortValue(x,key);if(v!==last)rank=i+1;x[prop]??={};x[prop][key]=rank;last=v})}
function renderMetrics(data){const a=data.alliance_roster.alliance||{},current=state.players.filter(x=>x.membership==='current'),ink=state.players.filter(x=>x.origin==='INK'),former=state.players.filter(x=>x.membership==='former'),total=current.reduce((s,x)=>s+(x.p.power||0),0);$('#metrics').innerHTML=[['Current BRO',current.length,`${a.count||current.length} reported by the API`],['Alliance power',fmt(total),`#${a.power_rank||'—'} in Kingdom 671`],['Tracked INK',ink.length,'Preserved for Swordland planning'],['Former BRO',former.length,'Retained as historical profiles']].map(x=>`<article class="metric"><small>${x[0]}</small><strong>${x[1]}</strong><em>${x[2]}</em></article>`).join('')}
function loadSwordlandSelections(){let roles=null,legacy=[];try{roles=JSON.parse(localStorage.getItem(swordlandRolesStorageKey)||'null')}catch{}try{legacy=JSON.parse(localStorage.getItem(swordlandStorageKey)||'[]')}catch{}const joiners=new Set((roles?.joiners||legacy).map(Number)),substitutes=new Set((roles?.substitutes||[]).map(Number));state.players.forEach(x=>{if(x.membership==='former'){x.swordlandRole='';x.swordland=false;return}x.swordlandRole=substitutes.has(x.id)?'substitute':joiners.has(x.id)?'joiner':x.swordlandRole||(x.swordland?'joiner':'');x.swordland=Boolean(x.swordlandRole)})}
function saveSwordlandSelections(){localStorage.setItem(swordlandRolesStorageKey,JSON.stringify({joiners:state.players.filter(x=>x.membership!=='former'&&x.swordlandRole==='joiner').map(x=>x.id),substitutes:state.players.filter(x=>x.membership!=='former'&&x.swordlandRole==='substitute').map(x=>x.id)}))}
function comparePlayers(a,b){if(state.sort==='name')return state.dir*a.p.nick_name.localeCompare(b.p.nick_name);const primary=state.dir*(sortValue(a,state.sort)-sortValue(b,state.sort));if(primary)return primary;if(state.sort==='rlevel')return (b.p.power||0)-(a.p.power||0);return a.p.nick_name.localeCompare(b.p.nick_name)}
function apply(){const q=state.query.toLowerCase();state.filtered=state.players.filter(x=>(!q||x.p.nick_name.toLowerCase().includes(q))&&(state.rank==='all'||x.p.alliance.rank_label===state.rank)&&(state.origin==='former'?x.membership==='former':state.origin==='all'?x.membership!=='former':state.origin==='current'?x.membership==='current':x.origin===state.origin&&x.membership!=='former')&&(state.event==='all'||(state.event==='swordland'&&x.swordland)||x.swordlandRole===state.event));state.filtered.sort(comparePlayers);render()}
function head(label,key){const active=state.sort===key;return`<button class="sort-head ${active?'active':''}" data-sort="${key}">${label}${active?(state.dir<0?' ↓':' ↑'):''}</button>`}
function originBadge(x){const label=x.membership==='former'?'EX-BRO':x.origin,cls=x.membership==='former'?'ex':x.origin.toLowerCase();return`<span class="origin-badge origin-${cls}">${label}</span>`}
function playerCell(x){const role=x.swordlandRole==='joiner'?'Swordland joiner':x.swordlandRole==='substitute'?'Swordland substitute':x.membership==='former'?'Former member':'';return`<div class="player"><img class="avatar" src="${esc(asset(x.p.avatar_url))}" alt="" loading="lazy"><div><b>${esc(x.p.nick_name)} ${originBadge(x)}</b><small>${tcLabel(x.p.town_center_level)}${role?` · ${role}`:''}</small></div></div>`}
function metricCell(value,aRank,kRank,cls='',label=''){return`<span class="num ${cls}" data-label="${esc(label)}"><b>${exact(value)}</b><small class="metric-ranks">A#${aRank||'—'} · K#${kRank||'—'}</small></span>`}
const sortChoices={overview:[['power','Power'],['kills','Kills'],['mystic','Mystic'],['name','Player name']],trials:[['mystic','Mystic'],['coliseum','Coliseum'],['forest','Forest'],['crystal','Crystal'],['knowledge','Knowledge'],['molten','Molten'],['radiant','Radiant'],['name','Player name']],heroes:[['power','Power'],['name','Player name']],gear:[['power','Power'],['name','Player name']],rankings:[['power','Power'],['migrant','Migration score'],['mystic','Mystic'],['name','Player name']],swordland:[['power','Power'],['rlevel','R rank, then power'],['mystic','Mystic'],['name','Player name']],tri:[['power','Power']]};
function updateMobileSort(){const choices=sortChoices[state.tab]||sortChoices.overview;const select=$('#mobileSort');select.innerHTML=choices.map(([value,label])=>`<option value="${value}">${label}</option>`).join('');select.value=state.sort;const direction=$('#mobileDir');direction.textContent=state.dir<0?'Descending ↓':'Ascending ↑';direction.setAttribute('aria-label',`Sort ${state.dir<0?'descending':'ascending'}; tap to reverse`)}
