function bind(){document.querySelectorAll('[data-id]').forEach(el=>{el.onclick=e=>{if(!e.target.closest('select,input,button'))openProfile(+el.dataset.id)};el.onkeydown=e=>{if(e.key==='Enter')openProfile(+el.dataset.id)}});document.querySelectorAll('[data-sort]').forEach(el=>el.onclick=()=>setSort(el.dataset.sort));document.querySelectorAll('[data-swordland-role]').forEach(el=>el.onchange=()=>toggleSwordland(+el.dataset.swordlandRole,el.dataset.role,el.checked));document.querySelectorAll('[data-availability-response]').forEach(el=>el.onchange=()=>setAvailabilityResponse(+el.dataset.availabilityResponse,el.value));document.querySelectorAll('[data-event-page]').forEach(el=>el.onclick=()=>openEventPage(el.dataset.eventPage));document.querySelectorAll('[data-building-role]').forEach(el=>el.onchange=()=>setBuildingRole(el.dataset.buildingRole,el.dataset.role,el.value));document.querySelectorAll('[data-team-player]').forEach(el=>el.onchange=()=>setTeam(+el.dataset.teamPlayer,el.value));document.querySelectorAll('[data-fixed-player]').forEach(el=>el.onchange=()=>setFixed(+el.dataset.fixedPlayer,el.checked));document.querySelectorAll('[data-looter-window]').forEach(el=>el.onchange=()=>setLooter(el.dataset.looterWindow,el.dataset.team,el.value));$('#copySwordland')?.addEventListener('click',copySwordlandRoster);$('#copyDiscord')?.addEventListener('click',copyDiscordMessage);$('#clearSwordland')?.addEventListener('click',clearSwordlandRoster);$('#clearAvailable')?.addEventListener('click',clearAvailabilityResponses);$('#unlockPlanner')?.addEventListener('click',()=>requestPlannerAccess(()=>render()));$('#lockPlanner')?.addEventListener('click',lockPlanner);$('#balanceTeams')?.addEventListener('click',balanceTeams);$('#resetTeams')?.addEventListener('click',resetTeams);$('#clearBuildings')?.addEventListener('click',clearBuildingAssignments);$('#clearLooters')?.addEventListener('click',clearLooters)}
function render(){document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===state.tab));$('#swordlandTabCount').textContent=state.players.filter(x=>x.membership!=='former'&&x.swordland).length;updateMobileSort();$('#sectionIntro').textContent='';$('.workspace').classList.toggle('event-workspace',state.tab==='swordland'||state.tab==='tri');$('.toolbar').hidden=state.tab==='tri'||(state.tab==='swordland'&&['buildings','reinforcers','looters','final'].includes(state.swordlandPage));({overview:renderOverview,trials:renderTrials,heroes:renderHeroes,gear:renderGear,rankings:renderRankings,swordland:renderSwordland,tri:renderTriAlliance}[state.tab])();const tracked=state.origin==='former'?state.players.filter(x=>x.membership==='former').length:state.players.filter(x=>x.membership!=='former').length;$('#resultCount').textContent=state.tab==='tri'?'Private planning area':state.tab==='swordland'&&state.swordlandPage!=='participants'?`${availablePlayers().length} available this week`:`${state.filtered.length} of ${tracked} players`;bind()}
function renderOverview(){$('#sectionIntro').textContent='Public privacy-filtered view. Current BRO and INK guests are shown by default; choose Former BRO to inspect retained snapshots. A# excludes former players.';$('#tableHead').className='table-head';$('#tableHead').innerHTML=`${head('Player','name')}<span class="sort-head">Alliance</span>${head('Power','power')}${head('Kills','kills')}${head('Mystic','mystic')}`;$('#playerList').className='player-list';$('#playerList').innerHTML=state.filtered.map(x=>`<article class="player-row" data-id="${x.id}" tabindex="0">${playerCell(x)}<span class="rank-pill" data-label="Alliance">${esc(x.p.alliance.rank_label)}</span>${metricCell(x.p.power,x.aRanks?.power,x.r?.power_rank,'','Power')}${metricCell(x.p.kills,x.aRanks?.kills,x.r?.kills_rank,'','Kills')}${metricCell(x.r?.mystic_trial,x.aRanks?.mystic,x.r?.mystic_rank,'mystic','Mystic')}</article>`).join('')||empty()}
const trials=[['Mystic','mystic','Mystic Trial'],['Coliseum','coliseum','Coliseum'],['Forest','forest','Forest of Life'],['Crystal','crystal','Crystal Cave'],['Knowledge','knowledge','Knowledge Nexus'],['Molten','molten','Molten Fort'],['Radiant','radiant','Radiant Spire']];
function trialLocalRank(x,key){return x.membership==='current'?`BRO#${x.broRanks?.[key]||'—'}`:x.membership==='guest'?`Pool#${x.poolRanks?.[key]||'—'}`:'BRO#—'}
