function renderTrials(){const broCount=state.players.filter(x=>x.membership==='current').length,poolCount=state.players.filter(x=>x.membership!=='former').length;$('#sectionIntro').textContent=`Individual trial levels are available for every tracked player. BRO# ranks all ${broCount} current BRO members; Pool# ranks INK guests within the ${poolCount}-player planning pool. K# is supplied by the API only for kingdom top-100 results.`;$('#tableHead').className='table-head trials-head';$('#tableHead').innerHTML=`${head('Player','name')}${trials.map(t=>head(t[0],t[1])).join('')}`;$('#playerList').className='player-list';$('#playerList').innerHTML=state.filtered.map(x=>`<article class="player-row trials-row" data-id="${x.id}">${playerCell(x)}${trials.map(t=>trialCell(x,t[2],t[0],t[1])).join('')}</article>`).join('')||empty()}
function renderHeroes(){$('#sectionIntro').textContent='Current arena defence teams with the game artwork referenced by the API.';$('#tableHead').innerHTML='';$('#playerList').className='card-grid';$('#playerList').innerHTML=state.filtered.map(x=>`<article class="data-card" data-id="${x.id}"><div class="card-title">${playerCell(x)}</div><div class="portrait-strip">${x.heroes.map(h=>`<div class="portrait"><img src="${esc(asset(h.icon))}" alt="${esc(h.name)}" loading="lazy"><b>${esc(h.name)}</b><small>Lv ${h.level} · ${esc(h.star_label||'')}</small></div>`).join('')}</div></article>`).join('')||empty()}
