function renderGear(){$('#sectionIntro').textContent='Actual governor-equipment artwork for the profiles that expose gear. Hidden profiles remain private.';$('#tableHead').innerHTML='';$('#playerList').className='card-grid';$('#playerList').innerHTML=state.filtered.map(x=>`<article class="data-card" data-id="${x.id}"><div class="card-title">${playerCell(x)}</div><div class="gear-gallery">${gearTiles(x)}</div></article>`).join('')||empty()}
