function renderSwordland(){if(state.swordlandPage==='availability')return renderAvailability();if(state.swordlandPage==='buildings')return renderBuildings();if(state.swordlandPage==='reinforcers')return renderTeamBuilder();if(state.swordlandPage==='looters')return renderLooters();if(state.swordlandPage==='final')return renderFinalMessage();const candidates=state.filtered.filter(x=>x.membership!=='former'),joiners=state.players.filter(x=>x.membership!=='former'&&x.swordlandRole==='joiner').length,substitutes=state.players.filter(x=>x.membership!=='former'&&x.swordlandRole==='substitute').length,selected=joiners+substitutes;$('#sectionIntro').innerHTML=eventNav();$('#tableHead').innerHTML='';$('#playerList').className='swordland-setup';$('#playerList').innerHTML=`<div class="event-heading"><div><p class="eyebrow">SWORDLAND SUMMIT · CANDIDATE LIST</p><h2>Long-term candidate pool</h2><p>Maintain the broader Swordland list here. Joiners receive event-entry priority; Substitutes are added only after available Joiners. Former BRO profiles stay in history but cannot be selected.</p></div></div><div class="swordland-actions"><div><strong>${selected}</strong><span> candidates · ${joiners} Joiners · ${substitutes} Substitutes</span></div><div class="swordland-sort" aria-label="Swordland sorting">${head('Power','power')}${head('R rank → power','rlevel')}${head('Player','name')}</div><div><button id="copySwordland" type="button" ${selected?'':'disabled'}>Copy candidate list</button><button id="clearSwordland" type="button" ${selected?'':'disabled'}>Clear</button></div></div><div class="signup-list">${candidates.map(x=>`<div class="signup-row ${x.swordlandRole?`is-${x.swordlandRole}`:''}"><div class="signup-player"><img class="avatar" src="${esc(asset(x.p.avatar_url))}" alt="" loading="lazy"><span><b>${esc(x.p.nick_name)} ${originBadge(x)}</b><small>${tcLabel(x.p.town_center_level)} · ${esc(x.p.alliance.rank_label)} · Mystic ${exact(x.r?.mystic_trial)} · Ref #${x.id}</small></span></div><label class="role-choice joiner"><input type="checkbox" data-swordland-role="${x.id}" data-role="joiner" ${x.swordlandRole==='joiner'?'checked':''}><span>Joiner</span></label><label class="role-choice substitute"><input type="checkbox" data-swordland-role="${x.id}" data-role="substitute" ${x.swordlandRole==='substitute'?'checked':''}><span>Substitute</span></label></div>`).join('')||'<div class="empty">No roster players match those filters.</div>'}</div>`}
