const availabilityOptions=[['yes_lt20','Available · fewer than 20 TP'],['yes_20_40','Available · 20–40 TP'],['yes_40_plus','Available · more than 40 TP'],['no','No'],['unknown','Don’t know yet']];
const isAvailableResponse=value=>['yes_lt20','yes_20_40','yes_40_plus','available_unknown'].includes(value);
const tpLabel=value=>({yes_lt20:'<20 TP',yes_20_40:'20–40 TP',yes_40_plus:'40+ TP',available_unknown:'TP not recorded'}[value]||'Unavailable');
const tpRank=value=>({yes_40_plus:3,yes_20_40:2,yes_lt20:1,available_unknown:0}[value]??-1);
function availabilityResponse(id){return state.planner.availabilityResponses?.[id]||'unknown'}
function availablePlayers(){return state.players.filter(x=>x.membership!=='former'&&x.swordlandRole&&isAvailableResponse(availabilityResponse(x.id)))}
function renderAvailability(){$('#sectionIntro').innerHTML=eventNav();if(!state.plannerUnlocked)return privateGate('Unlock weekly availability','Availability and teleport responses are encrypted locally with the rest of your Swordland plan.');$('#tableHead').innerHTML='';$('#playerList').className='availability-planner';const allCandidates=state.players.filter(x=>x.swordlandRole),candidates=state.filtered.filter(x=>x.swordlandRole),available=availablePlayers(),joiners=available.filter(x=>x.swordlandRole==='joiner').length,substitutes=available.length-joiners;$('#playerList').innerHTML=`<div class="planner-top"><div><p class="eyebrow">SWORDLAND SUMMIT · WEEKLY STEP 1</p><h2>Availability and teleports</h2><p>Record the poll response exactly. Available Joiners are assigned first; available Substitutes remain the second-priority pool. TP bands feed the looter rotation.</p></div><div class="planner-actions"><span class="assignment-count"><b>${available.length}</b> available · ${joiners} Joiners · ${substitutes} Subs</span><button id="clearAvailable" type="button">Reset responses</button><button id="lockPlanner" type="button">Lock</button></div></div><div class="availability-sort"><span>Sort candidates</span>${head('Power','power')}${head('R rank → power','rlevel')}${head('Mystic','mystic')}${head('Player','name')}</div><div class="availability-grid">${candidates.map(x=>{const response=availabilityResponse(x.id),isAvailable=isAvailableResponse(response);return`<article class="availability-card ${isAvailable?'selected':''}"><img class="avatar" src="${esc(asset(x.p.avatar_url))}" alt="" loading="lazy"><span><b>${esc(x.p.nick_name)} ${originBadge(x)} <i class="roster-priority ${x.swordlandRole}">${x.swordlandRole==='joiner'?'Joiner':'Substitute'}</i></b><small>Power ${exact(x.p.power)} · ${esc(x.p.alliance.rank_label)} · Mystic ${exact(x.r?.mystic_trial)}</small></span><select data-availability-response="${x.id}" aria-label="Availability and teleports for ${esc(x.p.nick_name)}">${response==='available_unknown'?'<option value="available_unknown" selected>Available · TP not recorded</option>':''}${availabilityOptions.map(([value,label])=>`<option value="${value}" ${response===value?'selected':''}>${label}</option>`).join('')}</select></article>`}).join('')||'<div class="empty">No candidates match these filters.</div>'}</div>`}
function removePlayerFromPlan(id){delete state.planner.assignments[id];Object.values(state.planner.buildingAssignments).forEach(x=>{if(Number(x.attack)===id)x.attack=null;if(Number(x.garrison)===id)x.garrison=null});Object.values(state.planner.looterAssignments||{}).forEach(x=>{if(Number(x.A)===id)x.A=null;if(Number(x.B)===id)x.B=null})}
async function setAvailabilityResponse(id,response){const wasAvailable=isAvailableResponse(availabilityResponse(id));state.planner.availabilityResponses[id]=response;if(wasAvailable&&!isAvailableResponse(response))removePlayerFromPlan(id);await encryptPlanner();render()}
async function clearAvailabilityResponses(){if(!confirm('Reset every weekly poll response to “Don’t know yet”? Current building, reinforcer and looter assignments will be cleared.'))return;state.players.filter(x=>x.swordlandRole).forEach(x=>{state.planner.availabilityResponses[x.id]='unknown';removePlayerFromPlan(x.id)});await encryptPlanner();render()}
