function renderTeamBuilder(){$('#sectionIntro').innerHTML=eventNav();if(!state.plannerUnlocked)return privateGate('Unlock reinforcer planning','Reinforcer groups are encrypted locally and are never included in the public dashboard data.');$('#tableHead').innerHTML='';$('#playerList').className='team-builder';const weekly=availablePlayers(),reserved=new Set([...buildingRoleIds('attack'),...buildingRoleIds('garrison')]),joiners=weekly.filter(x=>!reserved.has(x.id)),buildingPlayers=weekly.filter(x=>reserved.has(x.id));const teams=['A','B','C','D'],prioritySort=(a,b)=>(a.swordlandRole==='joiner'?0:1)-(b.swordlandRole==='joiner'?0:1)||(b.r?.mystic_trial||0)-(a.r?.mystic_trial||0);const assigned=id=>state.planner.assignments[id]?.team||'';const card=x=>{const historical=historicalReinforcerTeam(x.id);return`<article class="team-player ${x.swordlandRole}" data-id="${x.id}"><div><b>${esc(x.p.nick_name)} ${originBadge(x)} ${rosterPriorityBadge(x)}</b>${historical?`<span class="history-team">Historical ${historical}</span>`:''}<small>${esc(x.p.alliance.rank_label)} · Mystic ${exact(x.r?.mystic_trial)} · ${tpLabel(availabilityResponse(x.id))}</small></div><select data-team-player="${x.id}" aria-label="Reinforcement group for ${esc(x.p.nick_name)}"><option value="">Unassigned</option>${teams.map(t=>`<option value="${t}" ${assigned(x.id)===t?'selected':''}>Group ${t}</option>`).join('')}</select><label class="fixed-toggle" title="Keep this player in place when balancing"><input type="checkbox" data-fixed-player="${x.id}" ${state.planner.assignments[x.id]?.fixed?'checked':''}> Fixed</label></article>`};const context=team=>{const attackers=buildingTeamPlayers(team,'attack'),holders=buildingTeamPlayers(team,'garrison'),base=holders.reduce((n,x)=>n+(x.r?.mystic_trial||0),0);return{attackers,holders,base,html:`<div class="building-team-context"><div><span>Attackers · shown only</span><p>${attackers.length?attackers.map(x=>esc(x.p.nick_name)).join(' · '):'None assigned'}</p></div><div><span>Garrison · ${exact(base)} Mystic counted</span><p>${holders.length?holders.map(x=>`${esc(x.p.nick_name)} (${exact(x.r?.mystic_trial)})`).join(' · '):'None assigned'}</p></div></div>`}};const column=(team,label)=>{const members=joiners.filter(x=>assigned(x.id)===team).sort(prioritySort),building=team?context(team):{base:0,html:''},reinforcerTotal=members.reduce((n,x)=>n+(x.r?.mystic_trial||0),0),total=reinforcerTotal+building.base;return`<section class="team-column ${team?'team-'+team.toLowerCase():'unassigned'}"><header><div><span>${team?`GROUP ${team}`:'POOL'}</span><h3>${label}</h3></div><div class="team-score"><b>${members.length}</b><small>${team?`${exact(total)} Mystic total`:'players'}</small></div></header>${building.html}<div class="team-stack">${members.map(card).join('')||'<p class="column-empty">No players here</p>'}</div></section>`};const unassigned=joiners.filter(x=>!assigned(x.id)),primaryCount=joiners.filter(x=>x.swordlandRole==='joiner').length,subCount=joiners.length-primaryCount;$('#playerList').innerHTML=`<div class="planner-top"><div><p class="eyebrow">SWORDLAND SUMMIT · WEEKLY STEP 3</p><h2>Organise reinforcers</h2><p>Available Joiners are listed and balanced first. Available Substitutes follow as reserve capacity. Team strength includes reinforcers plus each unique garrison holder’s Mystic score.</p></div><div class="planner-actions"><span class="assignment-count"><b>${primaryCount}</b> Joiners · ${subCount} Subs remaining</span><button id="balanceTeams" class="primary-action" type="button">Balance Joiners, then Subs</button><button id="resetTeams" type="button">Reset groups</button><button id="lockPlanner" type="button">Lock</button></div></div>${weekly.length?'':`<div class="stage-warning">No weekly players selected. Return to <button data-event-page="availability">Availability + TP</button> first.</div>`}<div class="team-summary">${teams.map(t=>{const m=joiners.filter(x=>assigned(x.id)===t),base=context(t).base,total=base+m.reduce((n,x)=>n+(x.r?.mystic_trial||0),0),j=m.filter(x=>x.swordlandRole==='joiner').length;return`<span><b>${t}</b> ${j}J + ${m.length-j}S · ${exact(total)} Mystic <small>${exact(base)} holder base</small></span>`}).join('')}</div><div class="team-grid">${column('',`Unassigned (${unassigned.length})`)}${teams.map(t=>column(t,`Reinforcers ${t}`)).join('')}</div><section class="historical-groups"><header><div><p class="eyebrow">1 NOV 2026 REFERENCE</p><h3>Historical reinforcer groups</h3></div><p>Reference only—these do not overwrite this week’s choices.</p></header><div>${teams.map(t=>`<article><b>${t}</b><p>${historicalReinforcerTeams[t].names.join(' · ')}</p></article>`).join('')}</div></section><section class="substitute-dock"><header><h3>Already allocated to buildings</h3><span>${buildingPlayers.length} excluded</span></header>${buildingPlayers.length?`<div>${buildingPlayers.map(x=>`<span>${esc(x.p.nick_name)} ${originBadge(x)} ${rosterPriorityBadge(x)} · Mystic ${exact(x.r?.mystic_trial)}</span>`).join('')}</div>`:'<p>No attackers or garrison holders assigned yet.</p>'}</section>`}
function playerAssignedTeams(id){const teams=new Set();const reinforcement=state.planner.assignments[id]?.team;if(reinforcement)teams.add(reinforcement);swordlandBuildings.forEach(building=>{const assignment=state.planner.buildingAssignments[building.id]||{};if(Number(assignment.attack)===id||Number(assignment.garrison)===id)teams.add(buildingTeam(building))});return[...teams]}
const looterWindows=[['0-20','0–20 min'],['20-40','20–40 min'],['40-60','40–60 min']];
function renderLooters(){$('#sectionIntro').innerHTML=eventNav();if(!state.plannerUnlocked)return privateGate('Unlock looter rotation','Looter choices and teleport information are encrypted locally with the rest of your plan.');$('#tableHead').innerHTML='';$('#playerList').className='looter-planner';const available=availablePlayers(),used=new Set(Object.values(state.planner.looterAssignments||{}).flatMap(x=>[Number(x?.A),Number(x?.B)]).filter(Boolean)),eligible=available.filter(x=>playerAssignedTeams(x.id).some(t=>t==='A'||t==='B')).sort((a,b)=>tpRank(availabilityResponse(b.id))-tpRank(availabilityResponse(a.id))||(a.swordlandRole==='joiner'?0:1)-(b.swordlandRole==='joiner'?0:1)||(b.r?.mystic_trial||0)-(a.r?.mystic_trial||0));const select=(window,team)=>{const value=Number(state.planner.looterAssignments[window]?.[team])||0,current=value?state.players.find(x=>x.id===value):null,choices=eligible.filter(x=>playerAssignedTeams(x.id).includes(team)&&(!used.has(x.id)||x.id===value));return`<label class="looter-slot team-${team.toLowerCase()}"><span>Team ${team} looter</span><select data-looter-window="${window}" data-team="${team}"><option value="">Select ${team} player…</option>${current&&!choices.some(x=>x.id===value)?`<option value="${value}" selected>${esc(current.p.nick_name)} · assignment changed</option>`:''}${choices.map(x=>`<option value="${x.id}" ${x.id===value?'selected':''}>${esc(x.p.nick_name)} · ${tpLabel(availabilityResponse(x.id))} · Mystic ${exact(x.r?.mystic_trial)} · ${x.swordlandRole==='joiner'?'Joiner':'Sub'}</option>`).join('')}</select>${current?`<small>${rosterPriorityBadge(current)} ${tpLabel(availabilityResponse(current.id))} · Team ${team}</small>`:'<small>Choose from this team’s assigned players</small>'}</label>`};const rows=looterWindows.map(([key,label])=>{const a=Number(state.planner.looterAssignments[key]?.A)||0,b=Number(state.planner.looterAssignments[key]?.B)||0,pa=state.players.find(x=>x.id===a),pb=state.players.find(x=>x.id===b),difference=pa&&pb?Math.abs((pa.r?.mystic_trial||0)-(pb.r?.mystic_trial||0)):null;return`<article class="looter-window"><header><div><span>ROTATION WINDOW</span><h3>${label}</h3></div><b>${difference==null?'Incomplete':`${exact(difference)} Mystic gap`}</b></header><div>${select(key,'A')}${select(key,'B')}</div></article>`}).join('');const completed=looterWindows.filter(([key])=>state.planner.looterAssignments[key]?.A&&state.planner.looterAssignments[key]?.B).length;$('#playerList').innerHTML=`<div class="planner-top"><div><p class="eyebrow">SWORDLAND SUMMIT · WEEKLY STEP 4</p><h2>Looter rotation</h2><p>Build two or three A/B pairs. Each incoming looter replaces the outgoing looter inside the same team, preserving reinforcement positions and team strength. Players with more teleports are listed first.</p></div><div class="planner-actions"><span class="assignment-count"><b>${completed}</b> complete pairs</span><button id="clearLooters" type="button">Clear rotation</button><button id="lockPlanner" type="button">Lock</button></div></div><div class="looter-eligibility"><span><b>${eligible.filter(x=>tpRank(availabilityResponse(x.id))>=2).length}</b> players with 20+ TP</span><span><b>${eligible.length}</b> assigned to Team A or B</span><span>Joiners remain priority over Substitutes</span></div><div class="looter-grid">${rows}</div><section class="historical-groups looter-history"><header><div><p class="eyebrow">1 NOV 2026 REFERENCE</p><h3>Historical rotation</h3></div><p>Pipa / Leeloo · MŸTHÏC / Japadaratz · ElBarto / SmolShelbs</p></header></section>`}
async function setLooter(window,team,value){const id=value?Number(value):null;state.planner.looterAssignments??={};Object.values(state.planner.looterAssignments).forEach(pair=>{if(id&&Number(pair.A)===id)pair.A=null;if(id&&Number(pair.B)===id)pair.B=null});state.planner.looterAssignments[window]={...(state.planner.looterAssignments[window]||{}),[team]:id};await encryptPlanner();render()}
