const swordlandPlayerTarget=30;
function teamMemberIds(team){const ids=new Set(state.players.filter(x=>state.planner.assignments[x.id]?.team===team).map(x=>x.id));swordlandBuildings.filter(x=>buildingTeam(x)===team).forEach(building=>{const assignment=state.planner.buildingAssignments[building.id]||{};if(Number(assignment.attack))ids.add(Number(assignment.attack));if(Number(assignment.garrison))ids.add(Number(assignment.garrison))});return ids}
function allocatedPlayerIds(){return new Set(['A','B','C','D'].flatMap(team=>[...teamMemberIds(team)]))}
function discordMessage(){const teams=['A','B','C','D'],sections=teams.map(team=>{const reinforcers=state.players.filter(x=>state.planner.assignments[x.id]?.team===team).sort((a,b)=>a.p.nick_name.localeCompare(b.p.nick_name));return[`**TEAM ${team}**`,'⚔️ **Attack**',...discordLinesForRole(team,'attack'),'🛡️ **Garrison / Reinforce**',...discordLinesForRole(team,'garrison'),'➕ **Reinforcements**',...(reinforcers.length?reinforcers.map(x=>`• ${x.p.nick_name}`):['• None assigned'])].join('\n')});const rotation=looterWindows.flatMap(([key,label])=>{const pair=state.planner.looterAssignments[key]||{},a=state.players.find(x=>x.id===Number(pair.A)),b=state.players.find(x=>x.id===Number(pair.B));return a||b?[`• ${label} → Team A: ${a?.p.nick_name||'TBC'} · Team B: ${b?.p.nick_name||'TBC'}`]:[]});const assigned=new Set(state.players.filter(x=>playerAssignedTeams(x.id).length).map(x=>x.id)),substitutes=availablePlayers().filter(x=>x.swordlandRole==='substitute'&&!assigned.has(x.id)).sort((a,b)=>a.p.nick_name.localeCompare(b.p.nick_name));return[`⚔️ SWORDLAND TEAMS ⚔️`,...sections,'**LOOTER ROTATION**',...(rotation.length?rotation:['• None assigned']),'**SUBSTITUTE**',...(substitutes.length?substitutes.map(x=>`• ${x.p.nick_name}`):['• None'])].join('\n\n')}
function finalValidation(message){const checks=[];const add=(severity,text)=>checks.push({severity,text});swordlandBuildings.forEach(building=>{if(!state.planner.buildingAssignments[building.id]?.attack)add('error',`${building.name} has no attacker.`);if(!state.planner.buildingAssignments[building.id]?.garrison)add('error',`${building.name} has no garrison holder.`)});availablePlayers().filter(x=>x.swordlandRole==='joiner').forEach(x=>{const teams=playerAssignedTeams(x.id);if(!teams.length)add('error',`${x.p.nick_name} is an available Joiner but has no team.`);if(teams.length>1)add('error',`${x.p.nick_name} appears in more than one team (${teams.join(', ')}).`)});availablePlayers().filter(x=>x.swordlandRole==='substitute').forEach(x=>{const teams=playerAssignedTeams(x.id);if(teams.length>1)add('error',`${x.p.nick_name} appears in more than one team (${teams.join(', ')}).`)});const allocated=allocatedPlayerIds().size;if(allocated!==swordlandPlayerTarget)add('error',`${allocated} of ${swordlandPlayerTarget} players have been allocated to teams.`);const completed=looterWindows.filter(([key])=>state.planner.looterAssignments[key]?.A&&state.planner.looterAssignments[key]?.B).length;if(completed<2)add('error','Choose at least two complete A/B looter pairs.');looterWindows.forEach(([key,label])=>{const pair=state.planner.looterAssignments[key]||{};if(Boolean(pair.A)!==Boolean(pair.B))add('error',`${label} has only one looter selected.`);['A','B'].forEach(team=>{const id=Number(pair[team]);if(!id)return;if(!playerAssignedTeams(id).includes(team))add('error',`${state.players.find(x=>x.id===id)?.p.nick_name||'A looter'} is no longer assigned to Team ${team}.`);if(tpRank(availabilityResponse(id))<2)add('warning',`${state.players.find(x=>x.id===id)?.p.nick_name||'A looter'} has fewer than 20 TP or no recorded TP band.`)})});if(message.length>2000)add('error',`Discord message is ${message.length} characters; the standard limit is 2,000.`);return checks}
function renderFinalMessage(){$('#sectionIntro').innerHTML=eventNav();if(!state.plannerUnlocked)return privateGate('Unlock final message','The final teams and Discord output are generated from your encrypted local plan.');$('#tableHead').innerHTML='';$('#playerList').className='final-message-planner';const message=discordMessage(),checks=finalValidation(message),errors=checks.filter(x=>x.severity==='error'),warnings=checks.filter(x=>x.severity==='warning'),ready=!errors.length,allocated=allocatedPlayerIds().size,teams=['A','B','C','D'];$('#playerList').innerHTML=`<div class="planner-top"><div><p class="eyebrow">SWORDLAND SUMMIT · FINAL OUTPUT</p><h2>Discord-ready teams</h2><p>This follows the approved handoff order and leaves balancing calculations out of the published message. Looters remain listed inside their teams and repeat in the timed rotation.</p></div><div class="planner-actions"><span class="publish-state ${ready?'ready':'draft'}"><b>${ready?'Ready':'Draft'}</b><small>${errors.length} errors · ${warnings.length} warnings</small></span><button id="copyDiscord" class="primary-action" type="button" ${ready?'':'disabled'}>Copy Discord message</button><button id="lockPlanner" type="button">Lock</button></div></div><section class="headcount-check ${allocated===swordlandPlayerTarget?'complete':'incomplete'}"><div><span>ALLOCATED PLAYERS</span><b>${allocated} <small>/ ${swordlandPlayerTarget}</small></b><p>Distinct team members; multiple roles and looter rotations count once.</p></div><div class="headcount-teams">${teams.map(team=>`<span><b>${team}</b><strong>${teamMemberIds(team).size}</strong><small>players</small></span>`).join('')}</div></section><div class="final-output-grid"><section class="validation-panel"><header><p class="eyebrow">PUBLISH CHECK</p><h3>${ready?'Ready to publish':'Finish the plan first'}</h3></header>${checks.length?`<ul>${checks.map(x=>`<li class="${x.severity}"><b>${x.severity==='error'?'Fix':'Check'}</b><span>${esc(x.text)}</span></li>`).join('')}</ul>`:'<div class="all-clear"><b>✓</b><p>All required roles, Joiners, looter pairs, headcount and team memberships pass validation.</p></div>'}<small>${message.length} / 2,000 Discord characters</small></section><section class="discord-preview"><header><div><span class="discord-mark">Discord</span><b>Message preview</b></div><span>${ready?'Publishable':'Locked until checks pass'}</span></header><pre>${esc(message)}</pre></section></div>`}
async function copyDiscordMessage(){const button=$('#copyDiscord'),text=discordMessage();try{await navigator.clipboard.writeText(text)}catch{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();document.execCommand('copy');area.remove()}button.textContent='Copied for Discord ✓';setTimeout(()=>button.textContent='Copy Discord message',1800)}
function renderTriAlliance(){$('#sectionIntro').innerHTML='<nav class="event-nav"><button class="active">Overview</button><button disabled>Team planning · next</button><button disabled>Output · next</button></nav>';if(!state.plannerUnlocked)return privateGate('Tri-Alliance command room','This private area is ready for its planning pages once the event rules and alliance inputs are confirmed.');$('#tableHead').innerHTML='';$('#playerList').className='tri-shell';$('#playerList').innerHTML=`<div class="planner-top"><div><p class="eyebrow">TRI-ALLIANCE</p><h2>Command room</h2><p>The secure event shell is in place. Next we can add the event-specific roster, team logic, roles and Discord output without mixing it into Swordland.</p></div><button id="lockPlanner" type="button">Lock private pages</button></div><div class="coming-grid"><article><span>01</span><h3>Inputs</h3><p>Alliance rosters and participation status.</p></article><article><span>02</span><h3>Organisation</h3><p>Teams, leaders, roles and event rules.</p></article><article><span>03</span><h3>Output</h3><p>Validation and Discord-ready instructions.</p></article></div>`}
function toggleSwordland(id,role,checked){const player=state.players.find(x=>x.id===id);if(!player||player.membership==='former')return;player.swordlandRole=checked?role:player.swordlandRole===role?'':player.swordlandRole;player.swordland=Boolean(player.swordlandRole);saveSwordlandSelections();apply()}
function swordlandText(){const group=role=>state.players.filter(x=>x.swordlandRole===role).sort((a,b)=>a.p.nick_name.localeCompare(b.p.nick_name));const joiners=group('joiner'),substitutes=group('substitute');const lines=(title,players)=>`${title} (${players.length})\n${players.length?players.map(x=>`- ${x.p.nick_name} (Ref #${x.id})`).join('\n'):'- None'}`;return`BRO 671 Swordland roster (${joiners.length+substitutes.length})\n\n${lines('Joiners',joiners)}\n\n${lines('Substitutes',substitutes)}`}
async function copySwordlandRoster(){const button=$('#copySwordland');const text=swordlandText();try{await navigator.clipboard.writeText(text)}catch{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();document.execCommand('copy');area.remove()}button.textContent='Copied ✓';setTimeout(()=>button.textContent='Copy selected roster',1800)}
function clearSwordlandRoster(){if(!confirm('Clear all Swordland selections on this browser?'))return;state.players.forEach(x=>{x.swordland=false;x.swordlandRole=''});saveSwordlandSelections();apply()}
const bytesToB64=bytes=>btoa(String.fromCharCode(...bytes));
const b64ToBytes=value=>Uint8Array.from(atob(value),c=>c.charCodeAt(0));
async function derivePlanner(password,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:210000,hash:'SHA-256'},material,256);const key=await crypto.subtle.importKey('raw',bits,{name:'AES-GCM'},false,['encrypt','decrypt']);const proof=new Uint8Array(await crypto.subtle.digest('SHA-256',new Uint8Array([...new Uint8Array(bits),...new TextEncoder().encode('BRO671 planner verifier')])));return{key,proof}}
async function encryptPlanner(){if(!plannerCryptoKey)return;const iv=crypto.getRandomValues(new Uint8Array(12));const plain=new TextEncoder().encode(JSON.stringify(state.planner));const cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},plannerCryptoKey,plain));localStorage.setItem(plannerDataKey,JSON.stringify({iv:bytesToB64(iv),ciphertext:bytesToB64(cipher)}))}
async function decryptPlanner(key){const stored=JSON.parse(localStorage.getItem(plannerDataKey)||'null');if(!stored)return{assignments:{},buildingAssignments:{},availabilityResponses:null,looterAssignments:{}};const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(stored.iv)},key,b64ToBytes(stored.ciphertext));return JSON.parse(new TextDecoder().decode(plain))}
function requestPlannerAccess(next){if(state.plannerUnlocked)return next?.();plannerNext=next;const configured=Boolean(localStorage.getItem(plannerAuthKey));$('#plannerDialogTitle').textContent=configured?'Unlock planner':'Create planner password';$('#plannerDialogText').textContent=configured?'Enter your planner password. It is never uploaded or stored as readable text.':'Create one password for the private Swordland and Tri-Alliance planning pages.';$('#plannerSubmit').textContent=configured?'Unlock':'Create & unlock';$('#plannerConfirmWrap').hidden=configured;$('#plannerPassword').autocomplete=configured?'current-password':'new-password';$('#plannerPassword').value='';$('#plannerConfirm').value='';$('#plannerError').textContent='';$('#plannerDialog').showModal();setTimeout(()=>$('#plannerPassword').focus(),50)}
async function submitPlannerPassword(event){event.preventDefault();const password=$('#plannerPassword').value;const configured=JSON.parse(localStorage.getItem(plannerAuthKey)||'null');$('#plannerError').textContent='';if(!configured&&password!==$('#plannerConfirm').value){$('#plannerError').textContent='Passwords do not match.';return}if(password.length<8){$('#plannerError').textContent='Use at least 8 characters.';return}try{const salt=configured?b64ToBytes(configured.salt):crypto.getRandomValues(new Uint8Array(16));const derived=await derivePlanner(password,salt);if(configured&&bytesToB64(derived.proof)!==configured.verifier)throw new Error('wrong password');if(!configured)localStorage.setItem(plannerAuthKey,JSON.stringify({salt:bytesToB64(salt),verifier:bytesToB64(derived.proof)}));plannerCryptoKey=derived.key;state.planner=await decryptPlanner(derived.key);state.planner.assignments??={};state.planner.buildingAssignments??={};state.planner.looterAssignments??={};if(!state.planner.availabilityResponses){const legacy=new Set((state.planner.availablePlayerIds||state.players.filter(x=>x.swordlandRole==='joiner').map(x=>x.id)).map(Number));state.planner.availabilityResponses=Object.fromEntries(state.players.filter(x=>x.swordlandRole).map(x=>[x.id,legacy.has(x.id)?'available_unknown':'unknown']))}state.players.filter(x=>x.membership==='former').forEach(x=>removePlayerFromPlan(x.id));state.plannerUnlocked=true;await encryptPlanner();$('#plannerDialog').close();const next=plannerNext;plannerNext=null;next?.()}catch{$('#plannerError').textContent='That password could not unlock the planner.'}}
async function setBuildingRole(building,role,value){const id=value?Number(value):null;state.planner.buildingAssignments[building]={...(state.planner.buildingAssignments[building]||{}),[role]:id};if(id){delete state.planner.assignments[id];if(role==='attack')Object.entries(state.planner.buildingAssignments).forEach(([key,x])=>{if(Number(x.garrison)===id&&!(key==='swordshrine'&&building==='swordshrine'))x.garrison=null})}await encryptPlanner();render()}
async function clearBuildingAssignments(){if(!confirm('Clear every attacker and garrison-holder assignment?'))return;state.planner.buildingAssignments={};await encryptPlanner();render()}
async function setTeam(id,team){state.planner.assignments[id]={...(state.planner.assignments[id]||{}),team};await encryptPlanner();render()}
async function setFixed(id,fixed){state.planner.assignments[id]={...(state.planner.assignments[id]||{}),fixed};await encryptPlanner()}
async function balanceTeams(){const teams=['A','B','C','D'],reserved=new Set([...buildingRoleIds('attack'),...buildingRoleIds('garrison')]);const joiners=availablePlayers().filter(x=>!reserved.has(x.id));const totals=Object.fromEntries(teams.map(t=>[t,buildingTeamPlayers(t,'garrison').reduce((n,x)=>n+(x.r?.mystic_trial||0),0)+joiners.filter(x=>state.planner.assignments[x.id]?.team===t).reduce((n,x)=>n+(x.r?.mystic_trial||0),0)]));const counts=Object.fromEntries(teams.map(t=>[t,joiners.filter(x=>state.planner.assignments[x.id]?.team===t).length]));const movable=joiners.filter(x=>!state.planner.assignments[x.id]?.fixed&&!state.planner.assignments[x.id]?.team).sort((a,b)=>(a.swordlandRole==='joiner'?0:1)-(b.swordlandRole==='joiner'?0:1)||(b.r?.mystic_trial||0)-(a.r?.mystic_trial||0));movable.forEach(x=>{const team=[...teams].sort((a,b)=>totals[a]-totals[b]||counts[a]-counts[b])[0];state.planner.assignments[x.id]={team,fixed:false};totals[team]+=x.r?.mystic_trial||0;counts[team]++});await encryptPlanner();render()}
async function resetTeams(){if(!confirm('Remove every Swordland team assignment? Participant selections will stay unchanged.'))return;state.planner.assignments={};await encryptPlanner();render()}
function lockPlanner(){plannerCryptoKey=null;state.plannerUnlocked=false;state.planner={assignments:{},buildingAssignments:{},availabilityResponses:{},looterAssignments:{}};if(state.tab==='swordland')state.swordlandPage='participants';render()}
function empty(){const label=state.event==='joiner'?'joiners':state.event==='substitute'?'substitutes':'participants';return`<div class="empty">${state.event!=='all'?`No Swordland ${label} have been selected yet.`:'No players match those filters.'}</div>`}
function profileStat(label,value,aRank,kRank,note=''){const ranks=[aRank!=null?`${state.profileRankPrefix||'A'}#${aRank}`:'',kRank!=null?`K#${kRank}`:''].filter(Boolean).join(' · ');return`<div class="stat"><span>${esc(label)}</span><b>${esc(value)}</b>${ranks?`<small>${ranks}</small>`:''}${note?`<small>${esc(note)}</small>`:''}</div>`}
function openProfile(id){const x=state.players.find(y=>y.id===id);if(!x)return;state.profileRankPrefix='A';const boards=(x.r?.leaderboards||[]).map(b=>{const trial=trials.find(t=>t[2]===b.name),local=trial?`${trialLocalRank(x,trial[1])} · `:'';return`<div><span>${esc(b.name)}</span><span><b>${esc(b.value_label||exact(b.value))}</b> · ${local}${esc(b.kingdom_rank_label||'K#—')}</span></div>`}).join(''),status=x.membership==='former'?'Former BRO · last retained snapshot':x.membership==='guest'?'INK Swordland guest':'Current BRO member';$('#profileContent').innerHTML=`<header class="profile-header"><img class="avatar" src="${esc(asset(x.p.avatar_url))}" alt=""><div><h2>${esc(x.p.nick_name)} ${originBadge(x)}</h2><p>${esc(x.p.alliance.rank_label)} · ${tcLabel(x.p.town_center_level)} · ${status}</p></div></header><div class="profile-grid"><section class="detail-card"><h3>Player intel</h3><div class="stat-grid">${profileStat('Power',exact(x.p.power),x.aRanks?.power,x.r?.power_rank)}${profileStat('Kills',exact(x.p.kills),x.aRanks?.kills,x.r?.kills_rank)}${profileStat('Mystic Trial',exact(x.r?.mystic_trial),x.aRanks?.mystic,x.r?.mystic_rank)}${profileStat('Migration score',exact(x.r?.migrant_score),x.aRanks?.migrant,x.r?.migrant_rank,'API transfer-ranking value; formula not returned')}</div></section><section class="detail-card"><h3>City & troops</h3><div class="stat-grid">${profileStat('City level',tcLabel(x.p.town_center_level),null,x.r?.town_center_rank)}${profileStat('Troop tier / count','Not returned')}</div><p class="data-note">The API output includes Town Center / TG level and hero or gear troop-type bonuses, but no troop-tier or troop-count field. T11 troops therefore cannot be verified from this response.</p></section><section class="detail-card"><h3>Kingdom leaderboards</h3><div class="leaderboard">${boards}</div></section><section class="detail-card"><h3>Arena defence heroes</h3><div class="portrait-strip">${x.heroes.map(h=>`<div class="portrait"><img src="${esc(asset(h.icon))}" alt="${esc(h.name)}"><b>${esc(h.name)}</b><small>Lv ${h.level}</small></div>`).join('')}</div></section><section class="detail-card"><h3>Governor gear</h3><div class="gear-gallery">${gearTiles(x)}</div></section></div>`;$('#profileDialog').showModal()}

